css:
/* package pages (full implementation, rescue and repair) (9 Nov): spec card in the hero, included/not included, Fit Check rows, other packages strip */
body.p-pkg .grid9{margin-top:4px}
body.p-pkg .spec{margin:14px 0 0;display:grid;border-top:2px solid var(--ink)}
body.p-pkg .spec div{display:grid;grid-template-columns:90px minmax(0,1fr);gap:16px;padding:12px 0;border-bottom:1px solid var(--line);align-items:baseline}
body.p-pkg .spec dd{margin:0;font-weight:600;font-size:16px;line-height:1.4}
body.p-pkg .fit.two-col{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:clamp(24px,4vw,56px)}
body.p-pkg .fit .lnk{color:var(--b5);font-weight:600}
body.p-pkg .inc-foot{display:flex;justify-content:space-between;align-items:center;gap:20px 40px;flex-wrap:wrap;margin-top:32px;padding-top:24px;border-top:1px solid var(--line)}
body.p-pkg .inc-foot .ask{font-weight:600}
body.p-pkg .fitsplit{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.35fr);gap:clamp(32px,5vw,72px);align-items:start}
body.p-pkg .fitsplit .side{position:sticky;top:110px;display:flex;flex-direction:column;gap:20px}
body.p-pkg .fitsplit .fit{grid-template-columns:1fr;gap:44px}
body.p-pkg .notsure-l{font-weight:600;font-size:18px;margin:0}
body.p-pkg .ptiles.plans .ptile{aspect-ratio:auto;min-height:340px}
body.p-pkg .ptile .price{font-family:var(--head);font-size:clamp(40px,3.6vw,54px);font-weight:600;letter-spacing:-.035em;line-height:1}
body.p-pkg .ptile .price small{font-size:15px;font-weight:500;letter-spacing:0;margin-left:6px;opacity:.85}
body.p-pkg .ptile .ds b{color:var(--white);font-weight:600}
body.p-pkg .ptile .min{align-self:flex-start;padding:3px 7px;background:rgba(255,255,255,.18);font-family:var(--label);font-size:13px;color:var(--white)}
body.p-pkg .sp-foot{display:flex;justify-content:space-between;align-items:flex-start;gap:24px 48px;flex-wrap:wrap;margin-top:24px}
body.p-pkg .sp-foot .fine{margin-top:0;max-width:760px}
body.p-pkg .story .big{font-family:var(--head);font-size:clamp(40px,4vw,56px);font-weight:600;letter-spacing:-.035em;line-height:1;color:var(--b3)}
body.p-pkg .lnav{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px}
body.p-pkg .lnav a{display:flex;flex-direction:column;gap:10px;justify-content:space-between;min-height:120px;padding:16px;background:var(--c);color:var(--white);font-family:var(--head);font-weight:600;font-size:18px;line-height:1.2;transition:transform .35s var(--ease)}
body.p-pkg .lnav a .mono{color:rgba(255,255,255,.8);font-size:11px;font-weight:400}
body.p-pkg .lnav a:hover{transform:translateY(-4px)}
body.p-pkg .lnav a:focus-visible{outline:3px solid var(--b6);outline-offset:3px}
body.p-pkg .grid9 .cell.core .nm{font-size:clamp(15px,1.75vw,24px);hyphens:auto;-webkit-hyphens:auto;overflow-wrap:break-word}
body.p-pkg #fitcheck .three .d{color:var(--muted)}
body.p-pkg .grid9 .cell.lt .lab{color:var(--ink)}
body.p-pkg .proof .num{white-space:nowrap}
@media (max-width:420px){body.p-pkg .proof .num{font-size:clamp(28px,9vw,40px)}body.p-pkg .proof .pf{min-width:0}}
body.p-pkg #others{padding-top:clamp(48px,6vw,80px)}
body.p-pkg .lnav a.lt{color:var(--ink)}body.p-pkg .lnav a.lt .mono{color:var(--ink)}
@media (max-width:1100px){body.p-pkg .lnav{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:860px){body.p-pkg .fitsplit,body.p-pkg .fit.two-col{grid-template-columns:1fr}body.p-pkg .fitsplit .side{position:static}}
@media (max-width:560px){body.p-pkg .grid9 .cell.core .nm{font-size:13px;hyphens:none;-webkit-hyphens:none}body.p-pkg .lnav{grid-template-columns:1fr 1fr}body.p-pkg .spec div{grid-template-columns:1fr;gap:2px}body.p-pkg .ptiles.plans .ptile{min-height:0}}


/* 404 layout */
.nf{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(32px,5vw,72px);align-items:center;padding-block:clamp(32px,6vw,72px)}
.nf h1{font-size:clamp(40px,6vw,76px);line-height:1.02;letter-spacing:-.03em;margin:10px 0 18px}
.nf .lead{max-width:56ch}
.nf .ways{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}
.nf .ways a.btn-s{display:inline-flex;align-items:center;min-height:48px;padding:0 18px;border:1.5px solid var(--ink);font-weight:600}
.nf .copy{transition:opacity .3s var(--ease),transform .3s var(--ease)}
.nf.playing .copy{opacity:0;transform:translateX(-64px);pointer-events:none}
.nf.focus{grid-template-columns:1fr}.nf.focus .copy{display:none}
@media (max-width:900px){.nf{grid-template-columns:1fr}}

/* Pipeline: the game box */
.playbox{scroll-margin-top:96px;--g-bg:#0E1A3A;--g-line:#9DB6E3;--g-soft:#C9D6EE;background:var(--g-bg);color:#fff;padding:14px;display:flex;flex-direction:column;gap:10px;width:min(440px,100%);justify-self:center;border-radius:4px;font-variant-numeric:tabular-nums;will-change:transform}
.nf.focus .playbox{width:min(620px,100%,max(300px,calc(100svh - 300px)));box-shadow:0 30px 80px -20px rgba(14,26,58,.55)}
.hud{display:flex;justify-content:space-between;align-items:baseline;gap:12px;font-size:13px;color:var(--g-soft)}
.hud .name{color:#fff;font-weight:700;font-size:15px;letter-spacing:.02em}
.hud .right{display:flex;align-items:baseline;gap:14px}
.hud .snd{background:none;border:0;padding:0;line-height:inherit;color:var(--g-soft);font:500 13px var(--body);cursor:pointer;text-decoration:underline;text-underline-offset:3px}
.hud .snd:focus-visible{outline:2px solid var(--g-line);outline-offset:2px}
.meter{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--g-soft)}
.pips{display:flex;gap:4px;flex:1}
.pips i{flex:1;height:6px;background:#1B2B57;border-radius:1px;transition:background .25s,transform .25s var(--bounce)}
.pips i.on{background:#2E9BD6;transform:scaleY(1.5)}
.screen{position:relative;aspect-ratio:1/1}
.screen canvas{display:block;width:100%;height:100%;outline:none;touch-action:none;transition:opacity .45s var(--ease)}
.screen canvas:focus-visible{outline:1px solid rgba(157,182,227,.35);outline-offset:3px}
.screen.demo canvas{opacity:.55}
.overlay{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;padding:16px;transition:opacity .3s,visibility 0s}
.overlay[hidden]{display:flex!important;opacity:0;visibility:hidden;transition:opacity .3s,visibility 0s .3s}
.overlay .big{font-size:clamp(26px,4vw,36px);font-weight:700;letter-spacing:-.01em;color:#fff;margin:0}
.overlay .sub{margin:-6px 0 0;color:var(--g-soft);font-size:14px}
.overlay .acts{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}
.overlay .btn{min-width:150px}
.overlay .exit{min-height:48px;padding:0 18px;background:transparent;border:1.5px solid var(--g-line);color:#fff;font:600 16px var(--body);cursor:pointer}
.overlay .exit:focus-visible{outline:2px solid #fff;outline-offset:2px}
.overlay .win{margin:0;max-width:32ch;color:#fff;font-size:15px}.overlay .win a{color:#fff;text-decoration:underline}
.keys{font-size:12px;color:var(--g-soft);text-align:center;margin:0}
.pad{--k:52px;display:grid;grid-template-columns:repeat(3,var(--k));grid-template-rows:repeat(3,var(--k));gap:4px;justify-content:center;touch-action:none;user-select:none;-webkit-user-select:none}
/* the D-pad is a nine-grid: four square keys and a square hub, corners left open; press and slide your thumb to steer */
.pad button,.pad .hub{background:#1B2B57;border:0;border-radius:0;color:#9DB6E3;display:flex;align-items:center;justify-content:center;cursor:pointer;touch-action:none;-webkit-tap-highlight-color:transparent}
.pad .up{grid-column:2;grid-row:1}.pad .left{grid-column:1;grid-row:2}.pad .hub{grid-column:2;grid-row:2;background:#14234C}.pad .right{grid-column:3;grid-row:2}.pad .down{grid-column:2;grid-row:3}
.pad button.on,.pad button:active{background:#355DA6;color:#fff}
.pad button:focus-visible{outline:2px solid var(--g-line);outline-offset:-4px}
@media (hover:hover) and (pointer:fine){.pad,.k-touch,#pz{display:none!important}}
@media not ((hover:hover) and (pointer:fine)){.k-key{display:none}}
.playbox [hidden]:not(.overlay){display:none!important}
.status{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
/* the rest of the page steps back while you play */
body.gaming header.top,body.gaming .final{opacity:.25;transition:opacity .5s var(--ease)}
/* On a phone the game takes the whole screen: board on top, thumb pad at the bottom, swipe anywhere */
@media (pointer:coarse){
  body.gaming{overflow:hidden;overscroll-behavior:none}
  .nf.focus .playbox{position:fixed;inset:0;z-index:1000;width:auto;max-width:none;border-radius:0;box-shadow:none;justify-content:space-between;
    padding:max(12px,env(safe-area-inset-top)) 14px max(14px,env(safe-area-inset-bottom));touch-action:none}
  .nf.focus .playbox{--bw:min(100%,calc(100svh - 330px))}
  .nf.focus .hud,.nf.focus .meter,.nf.focus .screen{width:var(--bw);align-self:center}   /* HUD, stage bar and board share one width and one left edge */
  .nf.focus .hud{white-space:nowrap}
  @media (max-width:359px){.nf.focus .hud .name{display:none}.nf.focus .hud{justify-content:flex-end}}   /* small phones: drop the title so the HUD stays on one line */
  .nf.focus .pad{--k:64px;gap:5px}
  @media (max-height:700px){.nf.focus .pad{--k:56px;gap:4px}}
  .nf.focus .keys{display:none}
  .nf.focus .playbox .pad[hidden]{display:grid!important;visibility:hidden}   /* keep the pad's space while paused so the board does not jump */
}
header.top,.final{transition:opacity .5s var(--ease)}
@media (prefers-reduced-motion:reduce){.nf .copy,.screen canvas,.overlay,.pips i,header.top,.final{transition:none}}

