  body.p-post .art{font-size:17px}
  body.p-post .ways{grid-template-columns:1fr}
  body.p-post .uses{grid-template-columns:1fr}
  body.p-post .use{min-height:0}
  body.p-post .use b{margin-top:6px}
  body.p-post .nx,body.p-post .rel{grid-template-columns:1fr}
  body.p-post .nx .ptile{min-height:0}
