body.p-post .steps3 li{counter-increment:s;background:var(--white);border:1px solid var(--line);border-top:6px solid var(--c);padding:20px 20px 22px;font-size:16px;line-height:1.55;display:flex;flex-direction:column;gap:10px;transition:transform .5s var(--bounce),box-shadow .4s var(--ease)}
body.p-post .steps3 li::before{content:counter(s);font-family:var(--head);font-size:40px;font-weight:600;letter-spacing:-.04em;line-height:1;color:var(--c2,var(--b5))}
