body.p-post .mgroups>div.lt{color:var(--ink)}
body.p-post .mgroups h3{color:inherit!important;font-size:19px}
body.p-post .mgroups>div.lt h3{color:var(--ink)!important}
body.p-post .art .mgroups ul{margin-top:12px;gap:10px}
body.p-post .art .mgroups li{font-size:15px;line-height:1.5}
body.p-post .art .mgroups li::before{background:currentColor;opacity:.7}
body.p-post .art .mgroups strong{color:inherit}
