.gx-note{padding:12px 18px;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}
.gx.building .pt{opacity:0;transform:translateY(12px) scale(.97)}
.gx.building.planned .pt{opacity:1;transform:none;background:var(--tint);border-color:var(--tint)}
.gx.building.planned .pt>*{opacity:0}
.gx.building.planned .pt::after{content:"";position:absolute;left:14px;top:16px;width:42%;height:8px;background:var(--b8)}
.gx.building .pt.in{background:var(--white);border-color:var(--line)}.gx.building .pt.in>*{opacity:1}.gx.building .pt.in::after{display:none}
