@keyframes gxflash{0%{box-shadow:0 0 0 0 rgba(53,93,166,0)}20%{box-shadow:0 0 0 3px rgba(53,93,166,.9)}100%{box-shadow:0 0 0 0 rgba(53,93,166,0)}}
.gx.building .bars i{transform:scaleY(0)}.gx.building .pt.in .bars i{transform:none}
.gx.building .ring .fg{stroke-dashoffset:226.2}.gx.building .pt.in .ring .fg{stroke-dashoffset:90.5}
.gp-low{display:grid;grid-template-columns:1fr 1fr;gap:clamp(24px,4vw,56px);margin-top:clamp(88px,9vw,120px)}
