@media (max-width:1080px){.gx{grid-template-columns:1fr}.gx-pick{display:grid;grid-template-columns:repeat(3,1fr)}.gx-pick .mono{grid-column:1/-1}.gx-pick button{grid-template-columns:1fr}.gx-pick button .g{grid-row:auto;margin:0 0 6px}.gx-how{display:none}}
