/* package pages (full implementation, rescue and repair) (9 Nov): spec card in the hero, included/not included, Fit Check rows, other packages strip */
body.p-pkg .grid9{margin-top:4px}
body.p-pkg .spec{margin:14px 0 0;display:grid;border-top:2px solid var(--ink)}
